BEGIN TRANSACTION;
CREATE TABLE category_translation (product_category_name TEXT NOT NULL PRIMARY KEY, product_category_name_english TEXT);
CREATE TABLE customers ("customer_id" TEXT NOT NULL, "customer_unique_id" TEXT, "customer_zip_code_prefix" TEXT, "customer_city" TEXT, "customer_state" TEXT, PRIMARY KEY (customer_id));
CREATE TABLE order_items ("order_id" TEXT NOT NULL REFERENCES orders(order_id), "order_item_id" INTEGER NOT NULL, "product_id" TEXT NOT NULL REFERENCES products(product_id), "seller_id" TEXT NOT NULL REFERENCES sellers(seller_id), "shipping_limit_date" TEXT, "price" REAL, "freight_value" REAL, PRIMARY KEY (order_id, order_item_id));
CREATE TABLE order_payments ("order_id" TEXT NOT NULL REFERENCES orders(order_id), "payment_sequential" INTEGER NOT NULL, "payment_type" TEXT, "payment_installments" INTEGER, "payment_value" INTEGER, PRIMARY KEY (order_id, payment_sequential));
CREATE TABLE order_reviews ("review_id" TEXT NOT NULL, "order_id" TEXT NOT NULL REFERENCES orders(order_id), "review_score" INTEGER, "review_comment_title" TEXT, "review_comment_message" TEXT, "review_creation_date" TEXT, "review_answer_timestamp" TEXT, PRIMARY KEY (review_id, order_id));
